+// Sales from the till: each dish sold uses one portion of its recipe per
+// `qty`. A sale line remembers what it used, for the variance report.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+/** True when a till ticket has been imported before. */
+export function ticketImported(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Records one sale line (`qty` of a dish on a ticket, sold at `soldAt`) and
+ * consumes its ingredients with ref `sale:<ticket>`. Throws not_enough_stock
+ * when an ingredient runs out; the caller undoes partial work.
+ */
+export function recordSale(store, { ticket, soldAt, dishId, qty }) {
+  const dish = getDish(store, dishId);
+  const recipe = getRecipe(store, dish.recipeId);
+  if (!Number.isInteger(qty) || qty < 1) throw new AppError("invalid_qty");
+  const uses = scaled(recipe, qty).filter((u) => u.qty > 0);
+  for (const u of uses) consume(store, u.itemId, u.qty, { at: soldAt, ref: `sale:${ticket}` });
+  store.data.sales ??= [];
+  const sale = { id: store.nextId("sale"), ticket, soldAt, dishId, qty, uses };
+  store.data.sales.push(sale);
+  return sale;
+}
